<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Sale; use App\Models\Tenant; use App\Services\SaleService; use App\Services\TenantDataGuard; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class SaleController extends Controller { public function store(Request $r,Tenant $t,TenantDataGuard $guard) { $d=$r->validate(['branch_id'=>['required','integer'],'customer_id'=>['nullable','integer'],'items'=>['required','array','min:1'],'items.*.product_id'=>['required','integer'],'items.*.quantity'=>['required','numeric','gt:0'],'items.*.unit_price'=>['required','numeric','min:0']]);$guard->sale($t->id,$d['branch_id'],$d['customer_id']??null,$d['items']);$s=DB::transaction(function()use($d,$t,$r){$s=Sale::create(['tenant_id'=>$t->id,'branch_id'=>$d['branch_id'],'customer_id'=>$d['customer_id']??null,'created_by'=>$r->user()->id]);foreach($d['items'] as $i)$s->items()->create($i+['line_total'=>$i['quantity']*$i['unit_price']]);$total=$s->items()->sum('line_total');$s->update(['subtotal'=>$total,'total'=>$total]);return $s;});return response()->json(['data'=>$s->load('items')],201); } public function complete(Tenant $t,Sale $sale,SaleService $s){abort_unless($sale->tenant_id===$t->id,404);return ['data'=>$s->complete($sale)];} }
